tool_input.command:
mkdir -p migrations/down && cat > migrations/002_stock_checks.sql <<'EOF'
-- Last line of defence for POST /orders: stock never goes negative, ordered quantities are positive.
-- Added NOT VALID so existing rows aren't scanned under lock; 003 validates them.
set lock_timeout = '5s';
alter table products add constraint products_stock_nonnegative check (stock >= 0) not valid;
alter table order_items add constraint order_items_quantity_positive check (quantity > 0) not valid;
EOF
cat > migrations/down/002_stock_checks.sql <<'EOF'
set lock_timeout = '5s';
alter table order_items drop constraint if exists order_items_quantity_positive;
alter table products drop constraint if exists products_stock_nonnegative;
EOF
cat > migrations/003_validate_stock_checks.sql <<'EOF'
-- Validation doesn't block writes.
alter table products validate constraint products_stock_nonnegative;
alter table order_items validate constraint order_items_quantity_positive;
EOF
cat > migrations/down/003_validate_stock_checks.sql <<'EOF'
-- Nothing to undo: validating a constraint has no reverse. Run down/002 to drop the constraints.
select 1;
EOF

cat >> test/app.test.ts <<'EOF'

const placeOrder = (token: string, body: unknown) =>
  fetch(`${base}/orders`, {
    method: "POST",
    headers: { ...as(token), "content-type": "application/json" },
    body: typeof body === "string" ? body : JSON.stringify(body),
  });

const stockOf = async (id: number) =>
  (await pool.query("select stock from products where id = $1", [id])).rows[0].stock as number;

test("POST /orders charges the total, reduces stock and returns the order", async () => {
  const before = [await stockOf(1), await stockOf(2)];
  // The same product twice is merged into one line.
  const res = await placeOrder("bob-token", {
    items: [{ productId: 1, quantity: 1 }, { productId: 2, quantity: 1 }, { productId: 1, quantity: 1 }],
  });
  assert.equal(res.status, 201);
  const order = await res.json();
  assert.equal(order.status, "paid");
  assert.equal(order.total_cents, 2 * 2000 + 1200);
  assert.deepEqual(order.items, [
    { product_id: 1, quantity: 2, price_cents: 2000 },
    { product_id: 2, quantity: 1, price_cents: 1200 },
  ]);
  assert.deepEqual([await stockOf(1), await stockOf(2)], [before[0] - 2, before[1] - 1]);
  const { rows } = await pool.query("select amount_cents from payment_calls where idempotency_key = $1", [`order-${order.id}`]);
  assert.deepEqual(rows, [{ amount_cents: 5200 }]);
  const mine = await (await fetch(`${base}/orders`, { headers: as("bob-token") })).json();
  assert.ok(mine.some((o: { id: number }) => o.id === order.id));
});

test("POST /orders rejects bad input with 400 and changes nothing", async () => {
  const stock = await stockOf(1);
  const orders = (await pool.query("select count(*)::int as n from orders")).rows[0].n;
  for (const body of [
    "{not json",
    {},
    { items: [] },
    { items: "x" },
    { items: [null] },
    { items: [{ productId: "1", quantity: 1 }] },
    { items: [{ productId: 1, quantity: 0 }] },
    { items: [{ productId: 1, quantity: -1 }] },
    { items: [{ productId: 1, quantity: 1.5 }] },
    { items: [{ productId: 1 }] },
    { items: [{ productId: 1, quantity: 1e12 }] },
  ]) {
    const res = await placeOrder("alice-token", body);
    assert.equal(res.status, 400, JSON.stringify(body));
    assert.ok((await res.json()).error.code);
  }
  assert.equal(await stockOf(1), stock);
  assert.equal((await pool.query("select count(*)::int as n from orders")).rows[0].n, orders);
});

test("POST /orders: unknown product is 404, too little stock is 409, nothing is charged", async () => {
  const charges = (await pool.query("select count(*)::int as n from payment_calls")).rows[0].n;
  const missing = await placeOrder("alice-token", { items: [{ productId: 1, quantity: 1 }, { productId: 999, quantity: 1 }] });
  assert.equal(missing.status, 404);
  assert.equal((await missing.json()).error.code, "product_not_found");
  const tooMany = await placeOrder("alice-token", { items: [{ productId: 3, quantity: 6 }] });
  assert.equal(tooMany.status, 409);
  assert.equal((await tooMany.json()).error.code, "insufficient_stock");
  assert.equal((await pool.query("select count(*)::int as n from payment_calls")).rows[0].n, charges);
  assert.equal(await stockOf(3), 5);
});

test("POST /orders sent 20 times at once never oversells and charges once per order", async () => {
  await pool.query("update products set stock = 5 where id = 3");
  const responses = await Promise.all(
    Array.from({ length: 20 }, (_, i) =>
      placeOrder(i % 2 ? "alice-token" : "bob-token", { items: [{ productId: 3, quantity: 1 }, { productId: 1, quantity: 1 }] }),
    ),
  );
  const statuses = responses.map((r) => r.status).sort();
  assert.equal(statuses.filter((s) => s === 201).length, 5);
  assert.equal(statuses.filter((s) => s === 409).length, 15);
  assert.equal(await stockOf(3), 0);
  const created = await Promise.all(responses.filter((r) => r.status === 201).map((r) => r.json()));
  const { rows } = await pool.query(
    "select idempotency_key from payment_calls where idempotency_key = any($1)",
    [created.map((o) => `order-${o.id}`)],
  );
  assert.equal(rows.length, 5);
});

test("POST /orders: a failed charge puts the stock back and marks the order failed", async (t) => {
  t.mock.method(payments, "charge", async () => {
    throw new Error("card declined");
  });
  const stock = await stockOf(2);
  const res = await placeOrder("alice-token", { items: [{ productId: 2, quantity: 3 }] });
  assert.equal(res.status, 502);
  assert.equal((await res.json()).error.code, "payment_failed");
  assert.equal(await stockOf(2), stock);
  const { rows } = await pool.query("select status from orders order by id desc limit 1");
  assert.equal(rows[0].status, "failed");
});
EOF
pnpm typecheck && pnpm test 2>&1 | tail -40

