}
console.log((await pool.query("select conname from pg_constraint where conname like '%stock%' or conname like '%quantity%'")).rows);
await migrate();
console.log((await pool.query("select conname, convalidated from pg_constraint where conname like '%stock%' or conname like '%quantity%'")).rows);
